/** @param {NS} ns */
export async function main(ns) {
  ns.disableLog('sleep');

  // BFS scan network
  const servers = new Set();
  const queue = ['home'];
  servers.add('home');
  while (queue.length > 0) {
    const host = queue.shift();
    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!servers.has(neighbor)) {
        servers.add(neighbor);
        queue.push(neighbor);
      }
    }
  }

  // Gain root on all servers
  for (const server of servers) {
    try {
      if (!ns.hasRootAccess(server)) {
        const ports = ns.getServerNumPortsRequired(server);
        if (ports <= 1) {
          ns.brutessh(server);
          ns.nuke(server);
        }
      }
    } catch (e) {}
  }

  // Main loop
  let target = 'n00dles';
  let lastTargetUpdate = 0;
  let loops = 0;

  while (true) {
    // Re-evaluate target every 30 loops
    if (loops % 30 === 0) {
      let maxMoney = 0;
      const playerLevel = ns.getHackingLevel();
      for (const server of servers) {
        try {
          if (ns.hasRootAccess(server) && 
              ns.getServerRequiredHackingLevel(server) <= playerLevel) {
            const money = ns.getServerMaxMoney(server);
            if (money > maxMoney) {
              maxMoney = money;
              target = server;
            }
          }
        } catch (e) {}
      }
    }

    try {
      const sec = ns.getServerSecurityLevel(target);
      const minSec = ns.getServerMinSecurityLevel(target);
      const money = ns.getServerMoneyAvailable(target);
      const maxMoney = ns.getServerMaxMoney(target);

      if (sec > minSec + 5) {
        await ns.weaken(target);
      } else if (money < 0.75 * maxMoney) {
        await ns.grow(target);
      } else {
        await ns.hack(target);
      }
    } catch (e) {}

    loops++;
    if (loops % 20 === 0) {
      ns.print(`Target: ${target}, Loop: ${loops}`);
    }
    await ns.sleep(100);
  }
}

