/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set(['home']);
  const queue = ['home'];
  const servers = [];

  // BFS to scan network
  while (queue.length > 0) {
    const host = queue.shift();
    servers.push(host);
    const peers = ns.scan(host);
    for (const peer of peers) {
      if (!visited.has(peer)) {
        visited.add(peer);
        queue.push(peer);
      }
    }
  }

  ns.tprint(`Found ${servers.length} servers`);
  ns.tprint(`Hacking level: ${ns.getHackingLevel()}`);

  const rooted = [];
  for (const host of servers) {
    if (host === 'home') continue;
    if (!ns.hasRootAccess(host)) {
      const ports = ns.getServerNumPortsRequired(host);
      if (ports <= 1) {
        try {
          if (ports === 1) ns.brutessh(host);
          ns.nuke(host);
          rooted.push(host);
        } catch (e) {}
      }
    } else {
      rooted.push(host);
    }
  }

  rooted.sort((a, b) => ns.getServerMaxMoney(b) - ns.getServerMaxMoney(a));

  ns.tprint(`\n=== Rooted Servers (by max money) ===`);
  for (const host of rooted) {
    const maxMoney = ns.getServerMaxMoney(host);
    const reqLevel = ns.getServerRequiredHackingLevel(host);
    const minSec = ns.getServerMinSecurityLevel(host);
    ns.tprint(`${host}: $${maxMoney.toLocaleString()}, req-level=${reqLevel}, min-sec=${minSec.toFixed(1)}`);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const queue = ['home'];
  const servers = [];

  while (queue.length > 0) {
    const host = queue.shift();
    if (visited.has(host)) continue;
    visited.add(host);
    servers.push(host);

    const neighbors = ns.scan(host);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }

  ns.tprint(`Hacking level: ${ns.getHackingLevel()}`);

  for (const host of servers) {
    if (host === 'home') continue;
    const maxMoney = ns.getServerMaxMoney(host);
    ns.tprint(`${host}: maxMoney=${maxMoney}`);
  }
}
